/***
 * MARK: System settings tabs
 * @description Single source of truth for the System Settings section tabs:
 *   id, label, and whether the settings footer's Reset control applies. The
 *   Notifications and UI panels persist immediately through their own
 *   controls (each with its own reset), so the footer Reset — which only
 *   restores the settings draft (+ Storage remount) — would be a misleading
 *   no-op there and is hidden. Every consumer (the SystemSettingsPage screen,
 *   SystemSettingsContent, unit tests, and the canary tab-bar suite) derives
 *   from this list so a new tab can never drift the expectations again.
 * @example SETTINGS_TABS.find((t) => t.id === 'ui') => { id: 'ui', label: 'UI', showFooterReset: false }
 ***/

export const SETTINGS_TABS = [
  { id: "harness", label: "Harness", showFooterReset: true },
  { id: "models", label: "Models", showFooterReset: true },
  { id: "engine", label: "Engine", showFooterReset: true },
  { id: "storage", label: "Storage", showFooterReset: true },
  { id: "notifications", label: "Notifications", showFooterReset: false },
  { id: "prompt-layout", label: "Prompt Layout", showFooterReset: false },
  { id: "ui", label: "UI", showFooterReset: false },
];

/***
 * MARK: SETTINGS_TAB_LABELS
 * @description Ordered tab labels derived from SETTINGS_TABS (render order).
 * @example SETTINGS_TAB_LABELS => ['Harness', 'Models', 'Engine', 'Storage', 'Notifications', 'UI']
 ***/
export const SETTINGS_TAB_LABELS = SETTINGS_TABS.map((tab) => tab.label);

/***
 * MARK: isFooterResetVisible
 * @description Whether the settings footer Reset applies to a section id.
 *   Unknown ids fail open (true) so a future tab without metadata keeps the
 *   legacy behaviour instead of silently losing its reset.
 * @example isFooterResetVisible('ui') => false
 * @param {string} sectionId - Active section id.
 * @returns {boolean} True when the footer Reset should render.
 ***/
export function isFooterResetVisible(sectionId) {
  if (typeof sectionId !== "string" || !sectionId) return true;
  const tab = SETTINGS_TABS.find((entry) => entry.id === sectionId);
  if (!tab) return true;
  return tab.showFooterReset !== false;
}

/***
 * MARK: SETTINGS_SEARCH_INDEX
 * @description Single source of truth mapping search terms to project
 *   settings locations. Each entry names the tab that renders the setting
 *   (`tab`), the human-readable tab name (`tabLabel`, stored per entry so
 *   consumers never index a map by a variable), and the DOM id to scroll to
 *   and highlight (`elementId`).
 * @example SETTINGS_SEARCH_INDEX.find((e) => e.id === 'git-repo') => { id: 'git-repo', tab: 'files', … }
 ***/
export const SETTINGS_SEARCH_INDEX = [
  { id: 'active-project', tab: 'project', tabLabel: 'Project', label: 'Active Project', keywords: ['project', 'switch', 'select', 'active'], elementId: 'active-project-select' },
  { id: 'project-name', tab: 'project', tabLabel: 'Project', label: 'Project Name', keywords: ['project', 'name', 'rename', 'title'], elementId: 'project-name-input' },
  { id: 'ai-harness', tab: 'project', tabLabel: 'Project', label: 'AI Harness', keywords: ['harness', 'engine', 'agent', 'pi', 'antigravity', 'mock', 'custom'], elementId: 'project-harness-select' },
  { id: 'default-model', tab: 'project', tabLabel: 'Project', label: 'Default AI Model', keywords: ['model', 'default', 'ai', 'llm', 'picker'], elementId: 'project-default-model-select' },
  { id: 'harness-command', tab: 'project', tabLabel: 'Project', label: 'Custom Harness Command', keywords: ['custom', 'command', 'cli', 'harness'], elementId: 'project-harness-command-input' },
  { id: 'accent-color', tab: 'project', tabLabel: 'Project', label: 'Accent Theme Color', keywords: ['accent', 'color', 'colour', 'theme', 'brand'], elementId: 'project-accent-color-input' },
  { id: 'visibility', tab: 'project', tabLabel: 'Project', label: 'Hide Project from Active List', keywords: ['hide', 'archive', 'visible', 'show'], elementId: 'project-visibility-toggle' },
  { id: 'max-auto-iterations', tab: 'project', tabLabel: 'Project', label: 'Max auto-iterations', keywords: ['retry', 'retries', 'iterations', 'failback', 'loop', 'budget'], elementId: 'project-retry-max-auto-iterations' },
  { id: 'max-transient-retries', tab: 'project', tabLabel: 'Project', label: 'Max transient retries', keywords: ['retry', 'retries', 'transient', 'infrastructure', 'timeout', 'budget'], elementId: 'project-retry-max-transient-retries' },
  { id: 'auto-iteration', tab: 'project', tabLabel: 'Project', label: 'Automatic iteration', keywords: ['automatic', 'iteration', 'auto', 'retry', 'rerun'], elementId: 'project-retry-auto-iteration' },
  { id: 'agent-timeout', tab: 'project', tabLabel: 'Project', label: 'Agent stage timeout', keywords: ['timeout', 'agent', 'minutes', 'ceiling', 'retry'], elementId: 'project-retry-agent-timeout' },
  { id: 'ci-timeout', tab: 'project', tabLabel: 'Project', label: 'CI stage timeout', keywords: ['timeout', 'ci', 'deploy', 'minutes', 'ceiling'], elementId: 'project-retry-ci-timeout' },
  { id: 'merge-timeout', tab: 'project', tabLabel: 'Project', label: 'Merge stage timeout', keywords: ['timeout', 'merge', 'minutes', 'ceiling'], elementId: 'project-retry-merge-timeout' },
  { id: 'model-aliases', tab: 'aliases', tabLabel: 'Aliases', label: 'Model Aliases', keywords: ['alias', 'aliases', 'nickname', 'model', 'small', 'medium', 'large'], elementId: 'model-aliases-section' },
  { id: 'app-url', tab: 'files', tabLabel: 'Files & Links', label: 'App URL', keywords: ['app', 'url', 'link', 'go to app', 'address', 'health'], elementId: 'project-applink-url-input' },
  { id: 'app-network-host', tab: 'files', tabLabel: 'Files & Links', label: 'Network Host Override', keywords: ['network', 'host', 'lan', 'app', 'override'], elementId: 'project-applink-network-input' },
  { id: 'app-health-endpoint', tab: 'files', tabLabel: 'Files & Links', label: 'Health Endpoint', keywords: ['health', 'endpoint', 'probe', 'app'], elementId: 'project-applink-health-input' },
  { id: 'app-status', tab: 'files', tabLabel: 'Files & Links', label: 'App Status', keywords: ['status', 'running', 'stopped', 'degraded', 'app'], elementId: 'project-applink-status-select' },
  { id: 'working-dir', tab: 'files', tabLabel: 'Files & Links', label: 'Working Directory', keywords: ['working', 'directory', 'cwd', 'root', 'folder', 'path'], elementId: 'project-cwd-input' },
  { id: 'notes-dir', tab: 'files', tabLabel: 'Files & Links', label: 'Notes Space Symlink Directory', keywords: ['notes', 'symlink', 'knowledge', 'directory', 'space'], elementId: 'project-notes-input' },
  { id: 'docs-dir', tab: 'files', tabLabel: 'Files & Links', label: 'Documentation Folder Name', keywords: ['docs', 'documentation', 'folder', 'directory', 'name'], elementId: 'project-docs-dir-input' },
  { id: 'kainbain-dir', tab: 'files', tabLabel: 'Files & Links', label: 'KainBain Folder Name', keywords: ['kainbain', 'state', 'folder', 'directory', 'sessions', 'name'], elementId: 'project-kainbain-dir-input' },
  { id: 'centralized-docs', tab: 'files', tabLabel: 'Files & Links', label: 'Link to Centralised Documentation', keywords: ['centralised', 'centralized', 'docs', 'symlink', 'link'], elementId: 'project-centralized-docs-input' },
  { id: 'git-repo', tab: 'files', tabLabel: 'Files & Links', label: 'Git Repository URL', keywords: ['git', 'repo', 'repository', 'remote', 'url', 'origin'], elementId: 'project-git-input' },
  { id: 'task-branches', tab: 'files', tabLabel: 'Files & Links', label: 'Use Task Branches', keywords: ['branch', 'branches', 'task', 'merge', 'git'], elementId: 'project-use-branches-input' },
  { id: 'preserve-review-diff', tab: 'files', tabLabel: 'Files & Links', label: 'Preserve PR Review Diff After Merge', keywords: ['review', 'diff', 'preserve', 'merge', 'pr'], elementId: 'project-preserve-review-diff-input' },
  { id: 'reset-review-baseline', tab: 'files', tabLabel: 'Files & Links', label: 'Reset Review Baseline On Each Merge', keywords: ['review', 'baseline', 'reset', 'merge'], elementId: 'project-reset-review-baseline-input' },
];

/***
 * MARK: scoreWord
 * @description Scores one index entry against a single normalized word: 3 for
 *   a label prefix match, 2 for a label substring, 1 for a keyword
 *   substring, 0 for no match. Scores rank `searchSettings` so label hits
 *   lead. A non-array `keywords` field scores 0 instead of throwing.
 * @example scoreWord({ label: 'Git Repository URL', keywords: ['git'] }, 'git') => 3
 * @param {Object} entry - One `SETTINGS_SEARCH_INDEX` entry.
 * @param {string} word - Lowercase query word.
 * @returns {number} Match score (0 = no match).
 ***/
const scoreWord = (entry, word) => {
  const label = String(entry?.label ?? '').toLowerCase();
  if (label.startsWith(word)) return 3;
  if (label.includes(word)) return 2;
  const keywords = Array.isArray(entry?.keywords) ? entry.keywords : [];
  if (keywords.some((keyword) => String(keyword).toLowerCase().includes(word))) return 1;
  return 0;
};

/***
 * MARK: searchSettings
 * @description Returns index entries matching a query (case-insensitive).
 *   Multi-word queries match when EVERY word hits (label substring or
 *   keyword substring), so "centralised docs folder" finds the docs-link
 *   setting however the words are ordered. Scores sum the per-word best
 *   hits, best matches first with index order breaking ties. Blank queries
 *   and non-matches return an empty array.
 * @example searchSettings('git') => [{ id: 'git-repo', tab: 'files', … }]
 * @param {string} query - Raw user input.
 * @returns {Array<Object>} Matching entries, ranked best-first.
 ***/
export const searchSettings = (query) => {
  const normalized = String(query ?? '').trim().toLowerCase();
  if (!normalized) return [];
  const words = normalized.split(/\s+/).filter(Boolean);
  return SETTINGS_SEARCH_INDEX.map((entry, index) => {
    let score = 0;
    for (const word of words) {
      const wordScore = scoreWord(entry, word);
      // One missed word disqualifies the entry (AND semantics).
      if (wordScore === 0) return null;
      score += wordScore;
    }
    return { entry, score, index };
  })
    .filter((hit) => hit !== null)
    .sort((first, second) => second.score - first.score || first.index - second.index)
    .map((hit) => hit.entry);
};

/***
 * MARK: findBestMatch
 * @description Returns the single best index entry for a query (for
 *   jump-on-Enter), or null when nothing matches.
 * @example findBestMatch('git') => { id: 'git-repo', tab: 'files', … }
 * @param {string} query - Raw user input.
 * @returns {Object|null} The best matching entry, if any.
 ***/
export const findBestMatch = (query) => searchSettings(query)[0] ?? null;

import { minutesToMs } from '../../utils/timeoutUnits';

/***
 * MARK: parseRetrySettings
 * @description Validates the Retry & Timeouts drafts into a save payload:
 *   blank drafts become null (clear = follow the global default), counts
 *   must be whole numbers >= 0 (0 disables that loop), timeout drafts are
 *   entered in minutes (decimals allowed, must be above 0) and persisted as
 *   whole milliseconds, and the tri-state switch maps default/enabled/
 *   disabled to null/true/false. Returns per-field errors keyed by draft
 *   name plus the payload (valid even when errors is non-empty — callers
 *   must check).
 * @example parseRetrySettings({ maxAutoIterations: '3', agentTimeoutMs: '', ... }) => { errors: {}, payload: { maxAutoIterations: 3, agentTimeoutMs: null, ... } }
 * @param {Object} drafts - Raw string drafts (timeout drafts in minutes) plus the tri-state switch value.
 * @returns {{ errors: Object, payload: Object }}
 ***/
export function parseRetrySettings(drafts) {
  const errors = {};
  const payload = {};
  /* eslint-disable security/detect-object-injection -- keys are compile-time constants at every parseCount/parseTimeout call below */
  const parseCount = (key, label) => {
    const raw = String(drafts[key] ?? '').trim();
    if (raw === '') {
      payload[key] = null;
      return;
    }
    if (!/^\d+$/.test(raw)) {
      errors[key] = `${label} must be a whole number (0 disables, blank follows the default).`;
      return;
    }
    payload[key] = Number(raw);
  };
  const parseTimeout = (key, label) => {
    const raw = String(drafts[key] ?? '').trim();
    if (raw === '') {
      payload[key] = null;
      return;
    }
    // Positive decimal minutes, no exponents or hex (same `^\d+$` pieces
    // the count parser uses, so no new lint surface).
    const parts = raw.split('.');
    const isDecimalMinutes =
      parts.length <= 2 && parts.every((part) => /^\d+$/.test(part));
    if (!isDecimalMinutes || Number(raw) <= 0) {
      errors[key] = `${label} must be a number of minutes above 0 (blank follows the default).`;
      return;
    }
    payload[key] = minutesToMs(raw);
  };
  parseCount('maxAutoIterations', 'Max auto-iterations');
  parseCount('maxTransientRetries', 'Max transient retries');
  payload.autoIterationEnabled =
    drafts.autoIterationEnabled === 'enabled'
      ? true
      : drafts.autoIterationEnabled === 'disabled'
        ? false
        : null;
  parseTimeout('agentTimeoutMs', 'Agent stage timeout');
  parseTimeout('ciTimeoutMs', 'CI stage timeout');
  parseTimeout('mergeTimeoutMs', 'Merge stage timeout');
  /* eslint-enable security/detect-object-injection */
  return { errors, payload };
}

import { useEffect, useRef, useState } from 'react';
import { useKainBain } from '../../context/KainBainContext';
import { SkillsSection } from './SkillsSection';
import { SelectDropdown } from '../common/SelectDropdown';
import { ProjectSettingsForm } from './ProjectSettingsForm';
import { WorkflowManagementPanel } from './WorkflowManagementPanel';
import { SettingsSearchInput } from './SettingsSearchInput';



/***
 * MARK: PROJECT_SETTINGS_TABS
 * @description Single source of truth for the Project Settings tab bar: every
 *   tab's section id, button label + icon, tab-title heading, and whether the
 *   tab shares the one mounted `ProjectSettingsForm` (edits survive switches
 *   between form tabs; workflows/skills render their own panels). Adding a
 *   tab means adding one entry here — the buttons, the `h2` titles, and the
 *   section allowlists below all derive from this list so they cannot drift.
 *   App-wide UI & Workspace customization is NOT one of them — it lives in
 *   System Settings (SystemSettingsPage, `/system-settings`); per-project
 *   visual branding stays here as the accent-color picker inside the form.
 * @example PROJECT_SETTINGS_TABS.map((tab) => tab.id) => ['project', 'aliases', 'files', 'workflows', 'skills']
 ***/
export const PROJECT_SETTINGS_TABS = [
  { id: 'project', label: 'Project Settings', buttonIcon: '📂', heading: 'Project Configuration', headingIcon: '⚙️', sharesProjectForm: true },
  { id: 'aliases', label: 'Aliases', buttonIcon: '🏷️', heading: 'Model Aliases', headingIcon: '🏷️', sharesProjectForm: true },
  { id: 'files', label: 'Files & Links', buttonIcon: '📁', heading: 'Files & Links', headingIcon: '📁', sharesProjectForm: true },
  { id: 'workflows', label: 'Named Workflows', buttonIcon: '🔀', heading: null, headingIcon: null, sharesProjectForm: false },
  { id: 'skills', label: 'Skills', buttonIcon: '🧩', heading: null, headingIcon: null, sharesProjectForm: false },
];

/***
 * MARK: PROJECT_SETTINGS_SECTIONS
 * @description Allowlisted sub-sections of the Project Settings page, derived
 *   from `PROJECT_SETTINGS_TABS` so the allowlist and the tab bar agree.
 * @example PROJECT_SETTINGS_SECTIONS.includes('aliases') => true
 ***/
export const PROJECT_SETTINGS_SECTIONS = PROJECT_SETTINGS_TABS.map((tab) => tab.id);

/***
 * MARK: PROJECT_FORM_SECTIONS
 * @description The project-related tabs share one mounted `ProjectSettingsForm`
 *   (edits survive tab switches); workflows/skills render their own panels.
 *   Derived from `PROJECT_SETTINGS_TABS` so a new form tab needs no second edit.
 * @example PROJECT_FORM_SECTIONS.includes('files') => true
 ***/
export const PROJECT_FORM_SECTIONS = PROJECT_SETTINGS_TABS.filter((tab) => tab.sharesProjectForm).map((tab) => tab.id);

// How the jump-to-setting highlight behaves: a short wait lets the newly
// selected tab render before scrolling, then the ring stays visible briefly
// so the eye lands on the right field before it clears.
const HIGHLIGHT_SHOW_DELAY_MS = 80;
const HIGHLIGHT_HIDE_DELAY_MS = 2100;

/***
 * MARK: ProjectSettings
 * @description A dedicated Project Management / Settings page for configuring
 * the active project across focused tabs — Project (basics + retry/timeouts),
 * Aliases (model aliases), Files & Links (paths, repos, app link) — plus
 * multiple named workflows, and skills. App-wide UI &
 * Workspace customization lives in System Settings (SystemSettingsPage,
 * `/system-settings`). Distinct from that platform-scoped screen, this page is
 * per-project and keeps the `/settings` route.
 * @example <ProjectSettings />
 ***/
export function ProjectSettings() {
  const { projects, activeProjectId, selectProject } = useKainBain();
  const activeProject = projects.find((p) => p.id === activeProjectId);
  const [settingsSection, setSettingsSection] = useState('project');
  // Fail-safe: an unknown section id (e.g. a stale 'ui' from before UI
  // customization moved to System Settings) falls back to the project form
  // instead of rendering a blank page.
  const effectiveSection = PROJECT_SETTINGS_SECTIONS.includes(settingsSection)
    ? settingsSection
    : 'project';
  // Jump-to-setting target: `{ id, at }` so repeating the same search still
  // re-fires the highlight effect below (object identity changes each time).
  // `at` is a monotonic counter (not Date.now()): the value only needs to be
  // unique per selection, and a counter keeps the update pure and testable.
  const [highlightTarget, setHighlightTarget] = useState(null);
  const highlightSeqRef = useRef(0);
  // Fail-safe: `effectiveSection` is always a known tab, but the lookup still
  // falls back to the first tab so a heading always renders (never blank).
  const activeTab = PROJECT_SETTINGS_TABS.find((tab) => tab.id === effectiveSection)
    ?? PROJECT_SETTINGS_TABS[0];
  // Unsaved-edits flag reported by the shared project form.
  const [formDirty, setFormDirty] = useState(false);
  // Focus targets for arrow-key tab navigation (automatic activation: moving
  // focus also selects the tab, matching the APG tabs pattern).
  const tabButtonRefs = useRef([]);
  const focusTabAt = (index) => {
    const count = PROJECT_SETTINGS_TABS.length;
    const wrapped = ((index % count) + count) % count;
    tabButtonRefs.current[wrapped]?.focus();
    handleSectionChange(PROJECT_SETTINGS_TABS[wrapped].id);
  };
  // Arrow-key navigation between tabs (APG automatic activation: moving
  // focus also selects the tab). Wired per-button rather than on the tablist
  // container so the handler always lives on a focusable element. Movement is
  // relative to the focused tab: if the dirty-guard blocks a switch, focus
  // and selection can briefly diverge, and focus-relative movement stays sane.
  const onTabKeyDown = (event, fromIndex) => {
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      focusTabAt(fromIndex + 1);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      focusTabAt(fromIndex - 1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      focusTabAt(0);
    } else if (event.key === 'End') {
      event.preventDefault();
      focusTabAt(PROJECT_SETTINGS_TABS.length - 1);
    }
  };

  /***
   * MARK: handleSectionChange
   * @description Tab switch guard: leaving the project-related tabs
   *   (Project/Aliases/Files & Links) with unsaved edits asks for
   *   confirmation first. Moving between project tabs never warns — the
   *   shared form stays mounted and keeps the edits.
   ***/
  const handleSectionChange = (nextSection) => {
    if (
      formDirty &&
      PROJECT_FORM_SECTIONS.includes(effectiveSection) &&
      !PROJECT_FORM_SECTIONS.includes(nextSection) &&
      typeof window !== 'undefined' &&
      typeof window.confirm === 'function' &&
      !window.confirm('You have unsaved changes. Switch tabs anyway?')
    ) {
      return;
    }
    setSettingsSection(nextSection);
  };

  /***
   * MARK: handleSearchSelect
   * @description Jumps to a search result: switches to the entry's tab, then
   *   the highlight effect scrolls the target into view and rings it.
   ***/
  const handleSearchSelect = (entry) => {
    if (!entry) return;
    handleSectionChange(entry.tab);
    highlightSeqRef.current += 1;
    setHighlightTarget({ id: entry.elementId, at: highlightSeqRef.current });
  };

  // Scrolls the search target into view and highlights it briefly. Guarded
  // for test DOMs without `scrollIntoView`, and no-ops when the target id
  // is not on the active tab (e.g. a conditional field). Cleanup removes the
  // ring from the previous target: without this, picking a second result
  // while the first ring is still showing would clear the first hide timer
  // and leave that ring stuck on forever.
  useEffect(() => {
    if (!highlightTarget) return undefined;
    const targetId = highlightTarget.id;
    const clearRing = () => {
      const el = typeof document !== 'undefined'
        ? document.getElementById(targetId)
        : null;
      el?.classList?.remove('ring-2', 'ring-primary', 'rounded-sm');
    };
    const showTimer = setTimeout(() => {
      const el = typeof document !== 'undefined'
        ? document.getElementById(targetId)
        : null;
      if (el) {
        if (typeof el.scrollIntoView === 'function') {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        el.classList.add('ring-2', 'ring-primary', 'rounded-sm');
      }
    }, HIGHLIGHT_SHOW_DELAY_MS);
    const hideTimer = setTimeout(clearRing, HIGHLIGHT_HIDE_DELAY_MS);
    return () => {
      clearTimeout(showTimer);
      clearTimeout(hideTimer);
      clearRing();
    };
  }, [highlightTarget, effectiveSection]);

  return (
    /* A named <section> landmark (NOT another <main>): the app shell already
       provides the single top-level <main id="main-content"> (App.jsx), and a
       nested main triggers axe landmark violations. A labelled section keeps
       the settings content inside a landmark without duplicating main. */
    <section
      aria-label="Project settings"
      className="flex-1 p-6 space-y-6 overflow-y-auto custom-scrollbar text-on-surface bg-surface-deep"
    >
      {/* Top section switcher (tabs left, settings search right) */}
      <div className="flex gap-2 justify-between items-center border-b border-border-standard pb-4">
        <div className="flex gap-2 flex-wrap" role="tablist" aria-label="Project settings sections">
        {PROJECT_SETTINGS_TABS.map((tab, index) => (
        <button
          key={tab.id}
          ref={(el) => { tabButtonRefs.current[index] = el; }}
          id={`project-settings-tab-${tab.id}`}
          type="button"
          role="tab"
          aria-selected={effectiveSection === tab.id}
          aria-controls="project-settings-tabpanel"
          onClick={() => handleSectionChange(tab.id)}
          onKeyDown={(event) => onTabKeyDown(event, index)}
          className={`px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-sm transition-all flex items-center gap-2 cursor-pointer ${
            effectiveSection === tab.id
              ? 'bg-primary text-on-primary font-bold shadow-sm'
              : 'bg-surface-container hover:bg-surface-container-high text-text-muted hover:text-on-surface'
          }`}
        >
          <span aria-hidden="true">{tab.buttonIcon}</span>
          <span>{tab.label}</span>
        </button>
        ))}
        </div>
        <div className="shrink-0">
          <SettingsSearchInput onSelect={handleSearchSelect} />
        </div>
      </div>

      <div
        id="project-settings-tabpanel"
        role="tabpanel"
        aria-labelledby={`project-settings-tab-${effectiveSection}`}
      >
      {PROJECT_FORM_SECTIONS.includes(effectiveSection) && (
        <div>
          {/* Every project-related tab gets an h2 tab title: the section
              components below use h3 subtitles, and starting at h3 would skip
              a heading level (axe heading-order violation). */}
          <h2 className="text-lg font-bold uppercase tracking-tight text-text-high mb-4 flex items-center gap-2 font-headline-md">
            <span className="text-primary">{activeTab.headingIcon}</span> {activeTab.heading}
          </h2>
          {effectiveSection === 'project' && (
            <>
              <div className="space-y-4 max-w-2xl mb-8">
                <div className="flex flex-col gap-2">
                  <label
                    htmlFor="active-project-select"
                    className="text-xs font-bold uppercase text-text-muted tracking-wider"
                  >
                    Active Project
                  </label>
                  <SelectDropdown
                    id="active-project-select"
                    ariaLabel="Active Project"
                    value={activeProjectId || ''}
                    onChange={selectProject}
                    options={projects.map((p) => ({ value: p.id, label: p.name }))}
                  />
                </div>
              </div>
            </>
          )}

          {/* One mounted form across the project-related tabs: edits survive
              tab switches because only the `section` prop changes. */}
          <ProjectSettingsForm
            key={activeProjectId}
            project={activeProject}
            projectId={activeProjectId}
            onProjectUpdated={selectProject}
            section={effectiveSection}
            onDirtyChange={setFormDirty}
          />
        </div>
      )}

      {effectiveSection === 'workflows' && (
        <WorkflowManagementPanel key={activeProjectId} projectId={activeProjectId} />
      )}

      {effectiveSection === 'skills' && (
        <SkillsSection key={activeProjectId} activeProjectId={activeProjectId} />
      )}
      </div>
    </section>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useKainBain } from '../../context/KainBainContext';
import { SkillsSection } from './SkillsSection';
